public (string Summary, int OriginalSentenceCount, int SummarySentenceCount) Summarize(string documentText, int maxSentences)
{
    var sentences = SplitSentences(documentText);

    if (sentences.Count <= maxSentences)
        return (string.Join(" ", sentences), sentences.Count, sentences.Count);

    var wordFrequencies = BuildWordFrequencies(sentences);
    var topSentences = sentences
        .Select((sentence, index) => (Sentence: sentence, Index: index, Score: ScoreSentence(sentence, wordFrequencies)))
        .OrderByDescending(s => s.Score)
        .Take(maxSentences)
        .OrderBy(s => s.Index)
        .Select(s => s.Sentence)
        .ToList();

    return (string.Join(" ", topSentences), sentences.Count, topSentences.Count);
}

